const queryClient = new QueryClient();
type FileRecord = { name: string; kind: string; size?: number };
type Finding = { id: string; severity: string; category: string; title: string; client: string; estimatedValue: number | null; calculation?: string | null; explanation: string; sources: string[]; recommendedAction: string; confidence: number; approvalStatus: string; evidence: string[]; chronology: string[]; originalScope: string; additionalWork: string; revenueAtRisk: number | null; status?: string };
type Commitment = { id: string; client: string; commitment: string; owner: string; dueDate: string | null; source: string; status: string; evidence: string; estimatedValue: number | null };
type Audit = { id: string; project: string; client: string; createdAt: string; isDemo: boolean; files: FileRecord[]; revenueAtRisk: number | null; findings: Finding[]; commitments: Commitment[]; scopeRows: { item: string; original: string; actual: string; difference: string; evidence: string; status: string; value: number | null }[]; insufficientData?: boolean; determinations?: string[]; cannotDetermine?: string[] };
